//! Links the Windows agent's icon and file description. Startup Apps uses
//! the executable metadata for the name and icon. The icon comes from
//! `../broscribe-app/assets/brand/windows/BroScribe.res`, generated by its
//! `examples/render_brand.rs`. Other targets link nothing.

use std::ffi::OsString;
use std::path::{Path, PathBuf};
use std::process::Command;

#[path = "build_support/resource_compiler.rs"]
mod resource_compiler_discovery;

use resource_compiler_discovery::sdk_resource_compiler;

fn registered_sdk_root(view: &str) -> Option<PathBuf> {
    let result = Command::new("reg.exe")
        .args([
            "query",
            r"HKLM\SOFTWARE\Microsoft\Windows Kits\Installed Roots",
            "/v",
            "KitsRoot10",
            view,
        ])
        .output()
        .ok()?;
    if !result.status.success() {
        return None;
    }
    String::from_utf8_lossy(&result.stdout)
        .lines()
        .find_map(|line| {
            let (name, value) = line.split_once("REG_SZ")?;
            (name.trim() == "KitsRoot10").then(|| PathBuf::from(value.trim()))
        })
}

fn resource_compiler() -> Option<OsString> {
    if let Some(compiler) = std::env::var_os("RC").filter(|value| !value.is_empty()) {
        return Some(compiler);
    }
    let sdk = std::env::var_os("WindowsSdkDir")
        .map(PathBuf::from)
        .and_then(|root| sdk_resource_compiler(&root))
        .or_else(|| {
            ["/reg:32", "/reg:64"]
                .into_iter()
                .filter_map(registered_sdk_root)
                .find_map(|root| sdk_resource_compiler(&root))
        })
        .or_else(|| {
            ["ProgramFiles(x86)", "ProgramFiles"]
                .into_iter()
                .filter_map(std::env::var_os)
                .map(|root| PathBuf::from(root).join("Windows Kits").join("10"))
                .find_map(|root| sdk_resource_compiler(&root))
        });
    sdk.or_else(|| {
        std::env::var_os("PATH").as_deref().and_then(|path| {
            std::env::split_paths(path)
                .map(|bin| bin.join("rc.exe"))
                .find(|compiler| compiler.is_file())
        })
    })
    .map(PathBuf::into_os_string)
}

const RC_HELP: &str =
    "Install the Windows 10 or 11 SDK (x64 tools) or set RC to the resource compiler's executable";

fn main() {
    let manifest = Path::new(env!("CARGO_MANIFEST_DIR"));
    let agent_rc = manifest.join("windows/agent.rc");
    let res = manifest
        .join("..")
        .join("broscribe-app")
        .join("assets")
        .join("brand")
        .join("windows")
        .join("BroScribe.res");
    println!("cargo:rerun-if-changed={}", res.display());
    println!("cargo:rerun-if-changed={}", agent_rc.display());
    for key in [
        "RC",
        "WindowsSdkDir",
        "ProgramFiles(x86)",
        "ProgramFiles",
        "PATH",
    ] {
        println!("cargo:rerun-if-env-changed={key}");
    }
    let target = |key: &str| std::env::var(key).unwrap_or_default();
    if target("CARGO_CFG_TARGET_OS") == "windows" && target("CARGO_CFG_TARGET_ENV") == "msvc" {
        // MSVC's linker takes a compiled resource file as an input.
        let out = PathBuf::from(std::env::var_os("OUT_DIR").expect("Cargo OUT_DIR"));
        let agent_res = out.join("agent.res");
        let compiler =
            resource_compiler().unwrap_or_else(|| panic!("rc.exe was not found. {RC_HELP}"));
        let result = Command::new(&compiler)
            .arg("/nologo")
            .args([
                "/d",
                concat!("BRO_VERSION_MAJOR=", env!("CARGO_PKG_VERSION_MAJOR")),
            ])
            .args([
                "/d",
                concat!("BRO_VERSION_MINOR=", env!("CARGO_PKG_VERSION_MINOR")),
            ])
            .args([
                "/d",
                concat!("BRO_VERSION_PATCH=", env!("CARGO_PKG_VERSION_PATCH")),
            ])
            .args([
                "/d",
                concat!("BRO_VERSION_TEXT=\"", env!("CARGO_PKG_VERSION"), "\""),
            ])
            .arg("/fo")
            .arg(&agent_res)
            .arg(&agent_rc)
            .status()
            .unwrap_or_else(|error| {
                panic!(
                    "could not start {}: {error}. {RC_HELP}",
                    Path::new(&compiler).display()
                )
            });
        assert!(
            result.success(),
            "compile the Windows agent version resource"
        );
        println!("cargo:rustc-link-arg-bins={}", res.display());
        println!("cargo:rustc-link-arg-bins={}", agent_res.display());
    }
}
